import { z } from "zod";
import { serpApiParams } from "../../../../schema/common.ts";

/** `bing_product` engine query parameters (https://serpapi.com/bing-product-api,
 *  read 2026-10-27). Mirror carries optionality only (D25). */
export const zBingProductQuery = z.strictObject({
    product_token: z.string().min(1).describe(
        "The token needed to retrieve specific product details. The token is generated by SerpApi using our Bing Shopping API.",
    ),
    ...serpApiParams,
});
